        "ruz-e": "day",
        "gozashte": "previous, past",
        "ruye": "on",
        "ragham-e": "figure of",
        "hezaar": "thousand",
        "tomaan": "tomans",
        "gharaar": "place (gharaar gereft = settled)",
        "gereft": "took",
        "resaanehaa": "the media",
        "oft": "drop, fall",
        "eghdaamaat-e": "measures, actions of",
